CREATE OR REPLACE FUNCTION public.public_app_shortcut_icons() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT variant_key::jsonb FROM public.cde_selected WHERE group_key='app_shortcut_icons' AND is_primary=true LIMIT 1),'{}'::jsonb) $$; REVOKE ALL ON FUNCTION public.public_app_shortcut_icons() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_app_shortcut_icons() TO anon,authenticated; COMMENT ON FUNCTION public.public_app_shortcut_icons() IS 'Public app shortcut appearance keys only.';